const base = "http://the VM's public address:18082";
const r1 = await fetch(`${base}/v2/disbursements?limit=3`);
const j1 = await r1.json();
console.log("first window status", r1.status);
console.log(JSON.stringify(j1, null, 1).slice(0, 1200));
const r2 = await fetch(`${base}/v2/disbursements?cursor=${encodeURIComponent(j1.cursor)}&limit=3`);
const j2 = await r2.json();
console.log("second window status", r2.status, "drained", j2.drained, "first id", j2.disbursements?.[0]?.id, "count", j2.disbursements?.length);
const r3 = await fetch(`${base}/v2/disbursements?cursor=${encodeURIComponent(j2.cursor)}&limit=3`);
const j3 = await r3.json();
console.log("third window drained", j3.drained, "count", j3.disbursements?.length, "cursor same as j2?", j3.cursor === j2.cursor);
return { j1, j2, j3 };

