input.code:
const r = await tools.microsandbox.sandbox_exec({
  name: "meridian-probe",
  command: ["python3", "-c", `
import json, urllib.request
base = "http://the VM's public address:18082"
out = {}
r = urllib.request.urlopen(f"{base}/v2/disbursements?limit=3", timeout=20)
w1 = json.load(r)
out["w1"] = {"status": r.status, "drained": w1["drained"], "count": len(w1["disbursements"]), "first": w1["disbursements"][0] if w1["disbursements"] else None, "cursor": w1["cursor"][:40]}
r = urllib.request.urlopen(f"{base}/v2/disbursements?cursor={urllib.parse.quote(w1['cursor'])}&limit=3", timeout=20)
w2 = json.load(r)
out["w2"] = {"drained": w2["drained"], "count": len(w2["disbursements"]), "first_id": w2["disbursements"][0]["id"] if w2["disbursements"] else None, "same_cursor": w2["cursor"] == w1["cursor"]}
r = urllib.request.urlopen(f"{base}/v2/disbursements?cursor={urllib.parse.quote(w2['cursor'])}&limit=3", timeout=20)
w3 = json.load(r)
out["w3"] = {"drained": w3["drained"], "count": len(w3["disbursements"]), "first_id": w3["disbursements"][0]["id"] if w3["disbursements"] else None}
# overlap check between w1 and w2
ids1 = {d["id"] for d in w1["disbursements"]}
ids2 = {d["id"] for d in w2["disbursements"]}
out["overlap_w1_w2"] = sorted(ids1 & ids2)
out["empty_cursor_window"] = None
try:
    r = urllib.request.urlopen(f"{base}/v2/disbursements?cursor={urllib.parse.quote(w3['cursor'])}&limit=3", timeout=20)
    w4 = json.load(r)
    out["empty_cursor_window"] = {"drained": w4["drained"], "count": len(w4["disbursements"])}
except Exception as e:
    out["empty_cursor_window"] = repr(e)
print(json.dumps(out))
`],
});
return r;

