input.code:
const script = `
import json, urllib.request, urllib.parse
base = "http://the VM's public address:18082"
out = {}
r = urllib.request.urlopen(base + "/v2/disbursements?limit=3", timeout=20)
w1 = json.load(r)
out["w1"] = {"drained": w1["drained"], "count": len(w1["disbursements"]), "first": w1["disbursements"][0] if w1["disbursements"] else None}
r = urllib.request.urlopen(base + "/v2/disbursements?cursor=" + urllib.parse.quote(w1["cursor"]) + "&limit=3", timeout=20)
w2 = json.load(r)
out["w2"] = {"drained": w2["drained"], "count": len(w2["disbursements"]), "first_id": w2["disbursements"][0]["id"] if w2["disbursements"] else None, "same_cursor": w2["cursor"] == w1["cursor"]}
r = urllib.request.urlopen(base + "/v2/disbursements?cursor=" + urllib.parse.quote(w2["cursor"]) + "&limit=3", timeout=20)
w3 = json.load(r)
out["w3"] = {"drained": w3["drained"], "count": len(w3["disbursements"]), "first_id": w3["disbursements"][0]["id"] if w3["disbursements"] else None}
ids1 = {d["id"] for d in w1["disbursements"]}
ids2 = {d["id"] for d in w2["disbursements"]}
out["overlap_w1_w2"] = sorted(ids1 & ids2)
out["w4"] = None
try:
    r = urllib.request.urlopen(base + "/v2/disbursements?cursor=" + urllib.parse.quote(w3["cursor"]) + "&limit=3", timeout=20)
    w4 = json.load(r)
    out["w4"] = {"drained": w4["drained"], "count": len(w4["disbursements"])}
except Exception as e:
    out["w4"] = repr(e)
print(json.dumps(out))
`;
const r = await tools.microsandbox.sandbox_shell({
  name: "meridian-probe",
  command: "python3 - <<'EOF'\n" + script + "EOF",
  timeout: 60,
});
return r;

